=== FILE: axi4_lite_regs.v ===
// axi4_lite_regs: four 32-bit read/write registers behind an AXI4-Lite
// subordinate port.
// Implements microarchitecture.md (holding registers, READY from state only,
// 1-cycle response latency) for interface_spec.md.
module axi4_lite_regs #(
    parameter integer ADDR_WIDTH = 4,
    parameter integer DATA_WIDTH = 32
) (
    input  wire                    aclk,
    input  wire                    aresetn,
    input  wire [ADDR_WIDTH-1:0]   s_axil_awaddr,
    input  wire                    s_axil_awvalid,
    output wire                    s_axil_awready,
    input  wire [DATA_WIDTH-1:0]   s_axil_wdata,
    input  wire [DATA_WIDTH/8-1:0] s_axil_wstrb,
    input  wire                    s_axil_wvalid,
    output wire                    s_axil_wready,
    output wire [1:0]              s_axil_bresp,
    output wire                    s_axil_bvalid,
    input  wire                    s_axil_bready,
    input  wire [ADDR_WIDTH-1:0]   s_axil_araddr,
    input  wire                    s_axil_arvalid,
    output wire                    s_axil_arready,
    output wire [DATA_WIDTH-1:0]   s_axil_rdata,
    output wire [1:0]              s_axil_rresp,
    output wire                    s_axil_rvalid,
    input  wire                    s_axil_rready
);

  localparam integer STRB_WIDTH  = DATA_WIDTH / 8;
  localparam [1:0]   RESP_OKAY   = 2'b00;
  localparam [1:0]   RESP_SLVERR = 2'b10;

  // ------------------------------------------------------------------
  // State
  // ------------------------------------------------------------------
  reg                  aw_held_q;
  reg                  w_held_q;
  reg                  bvalid_q;
  reg  [1:0]           bresp_q;
  reg                  rvalid_q;
  reg  [1:0]           rresp_q;
  reg  [DATA_WIDTH-1:0] rdata_q;

  // Datapath holding registers (not reset; gated by the held flags).
  reg  [ADDR_WIDTH-1:0] aw_addr_q;
  reg  [DATA_WIDTH-1:0] w_data_q;
  reg  [STRB_WIDTH-1:0] w_strb_q;

  // Register file: separate flops.
  reg  [DATA_WIDTH-1:0] reg0_q;
  reg  [DATA_WIDTH-1:0] reg1_q;
  reg  [DATA_WIDTH-1:0] reg2_q;
  reg  [DATA_WIDTH-1:0] reg3_q;

  // ------------------------------------------------------------------
  // Handshakes: READY is a function of state only
  // ------------------------------------------------------------------
  wire awready_w = !aw_held_q && !bvalid_q;
  wire wready_w  = !w_held_q && !bvalid_q;
  wire arready_w = !rvalid_q;

  wire aw_hs = s_axil_awvalid && awready_w;
  wire w_hs  = s_axil_wvalid && wready_w;
  wire ar_hs = s_axil_arvalid && arready_w;

  // The write fires on the edge that completes the AW/W pair.
  wire do_write = (aw_held_q || aw_hs) && (w_held_q || w_hs);

  wire [ADDR_WIDTH-1:0] wr_addr = aw_held_q ? aw_addr_q : s_axil_awaddr;
  wire [DATA_WIDTH-1:0] wr_data = w_held_q ? w_data_q : s_axil_wdata;
  wire [STRB_WIDTH-1:0] wr_strb = w_held_q ? w_strb_q : s_axil_wstrb;

  // ------------------------------------------------------------------
  // Address decode (SLVERR policy)
  // ------------------------------------------------------------------
  wire       wr_mapped = (wr_addr[1:0] == 2'b00) &&
                         ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
  wire [1:0] wr_idx    = wr_addr[3:2];

  wire       rd_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                         ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});
  wire [1:0] rd_idx    = s_axil_araddr[3:2];

  // ------------------------------------------------------------------
  // Byte merge
  // ------------------------------------------------------------------
  wire [DATA_WIDTH-1:0] wr_mask;

  genvar gi;
  generate
    for (gi = 0; gi < STRB_WIDTH; gi = gi + 1) begin : g_mask
      assign wr_mask[8*gi +: 8] = {8{wr_strb[gi]}};
    end
  endgenerate

  wire [DATA_WIDTH-1:0] reg0_merged = (reg0_q & ~wr_mask) | (wr_data & wr_mask);
  wire [DATA_WIDTH-1:0] reg1_merged = (reg1_q & ~wr_mask) | (wr_data & wr_mask);
  wire [DATA_WIDTH-1:0] reg2_merged = (reg2_q & ~wr_mask) | (wr_data & wr_mask);
  wire [DATA_WIDTH-1:0] reg3_merged = (reg3_q & ~wr_mask) | (wr_data & wr_mask);

  wire reg_we0 = do_write && wr_mapped && (wr_idx == 2'd0);
  wire reg_we1 = do_write && wr_mapped && (wr_idx == 2'd1);
  wire reg_we2 = do_write && wr_mapped && (wr_idx == 2'd2);
  wire reg_we3 = do_write && wr_mapped && (wr_idx == 2'd3);

  // ------------------------------------------------------------------
  // Read mux
  // ------------------------------------------------------------------
  reg [DATA_WIDTH-1:0] rd_word;

  always @* begin
    case (rd_idx)
      2'd0:    rd_word = reg0_q;
      2'd1:    rd_word = reg1_q;
      2'd2:    rd_word = reg2_q;
      2'd3:    rd_word = reg3_q;
      default: rd_word = {DATA_WIDTH{1'b0}};
    endcase
  end

  // ------------------------------------------------------------------
  // Next-state logic
  // ------------------------------------------------------------------
  reg                  aw_held_d;
  reg                  w_held_d;
  reg                  bvalid_d;
  reg  [1:0]           bresp_d;
  reg                  rvalid_d;
  reg  [1:0]           rresp_d;
  reg  [DATA_WIDTH-1:0] rdata_d;
  reg  [ADDR_WIDTH-1:0] aw_addr_d;
  reg  [DATA_WIDTH-1:0] w_data_d;
  reg  [STRB_WIDTH-1:0] w_strb_d;

  always @* begin
    aw_held_d = aw_held_q;
    w_held_d  = w_held_q;
    aw_addr_d = aw_addr_q;
    w_data_d  = w_data_q;
    w_strb_d  = w_strb_q;
    bvalid_d  = bvalid_q;
    bresp_d   = bresp_q;
    rvalid_d  = rvalid_q;
    rresp_d   = rresp_q;
    rdata_d   = rdata_q;

    // Write address / data capture.
    if (do_write) begin
      aw_held_d = 1'b0;
      w_held_d  = 1'b0;
    end else begin
      if (aw_hs) begin
        aw_held_d = 1'b1;
        aw_addr_d = s_axil_awaddr;
      end
      if (w_hs) begin
        w_held_d = 1'b1;
        w_data_d = s_axil_wdata;
        w_strb_d = s_axil_wstrb;
      end
    end

    // Write response. do_write needs bvalid_q low, so it never meets a B handshake.
    if (bvalid_q && s_axil_bready) begin
      bvalid_d = 1'b0;
    end
    if (do_write) begin
      bvalid_d = 1'b1;
      bresp_d  = wr_mapped ? RESP_OKAY : RESP_SLVERR;
    end

    // Read response. ar_hs needs rvalid_q low.
    if (rvalid_q && s_axil_rready) begin
      rvalid_d = 1'b0;
    end
    if (ar_hs) begin
      rvalid_d = 1'b1;
      rresp_d  = rd_mapped ? RESP_OKAY : RESP_SLVERR;
      rdata_d  = rd_mapped ? rd_word : {DATA_WIDTH{1'b0}};
    end
  end

  // ------------------------------------------------------------------
  // Registers
  // ------------------------------------------------------------------
  always @(posedge aclk) begin
    if (!aresetn) begin
      aw_held_q <= 1'b0;
      w_held_q  <= 1'b0;
      bvalid_q  <= 1'b0;
      bresp_q   <= RESP_OKAY;
      rvalid_q  <= 1'b0;
      rresp_q   <= RESP_OKAY;
      rdata_q   <= {DATA_WIDTH{1'b0}};
    end else begin
      aw_held_q <= aw_held_d;
      w_held_q  <= w_held_d;
      bvalid_q  <= bvalid_d;
      bresp_q   <= bresp_d;
      rvalid_q  <= rvalid_d;
      rresp_q   <= rresp_d;
      rdata_q   <= rdata_d;
    end
  end

  // Holding registers: datapath, not reset (microarchitecture section 2).
  always @(posedge aclk) begin
    aw_addr_q <= aw_addr_d;
    w_data_q  <= w_data_d;
    w_strb_q  <= w_strb_d;
  end

  always @(posedge aclk) begin
    if (!aresetn) begin
      reg0_q <= {DATA_WIDTH{1'b0}};
      reg1_q <= {DATA_WIDTH{1'b0}};
      reg2_q <= {DATA_WIDTH{1'b0}};
      reg3_q <= {DATA_WIDTH{1'b0}};
    end else begin
      if (reg_we0) reg0_q <= reg0_merged;
      if (reg_we1) reg1_q <= reg1_merged;
      if (reg_we2) reg2_q <= reg2_merged;
      if (reg_we3) reg3_q <= reg3_merged;
    end
  end

  // ------------------------------------------------------------------
  // Outputs
  // ------------------------------------------------------------------
  assign s_axil_awready = awready_w;
  assign s_axil_wready  = wready_w;
  assign s_axil_bvalid  = bvalid_q;
  assign s_axil_bresp   = bresp_q;
  assign s_axil_arready = arready_w;
  assign s_axil_rvalid  = rvalid_q;
  assign s_axil_rresp   = rresp_q;
  assign s_axil_rdata   = rdata_q;

  // ------------------------------------------------------------------
  // Design-intent properties
  // ------------------------------------------------------------------
`ifdef FORMAL
  reg f_past_valid;
  initial f_past_valid = 1'b0;
  always @(posedge aclk) f_past_valid <= 1'b1;

  always @(*) begin
    if (!f_past_valid) assume (!aresetn);
  end

  always @(*) begin
    if (f_past_valid) begin
      assert (!(aw_held_q && w_held_q));
      if (bvalid_q) assert (!aw_held_q && !w_held_q);
      assert (bresp_q == RESP_OKAY || bresp_q == RESP_SLVERR);
      assert (rresp_q == RESP_OKAY || rresp_q == RESP_SLVERR);
      if (rresp_q == RESP_SLVERR) assert (rdata_q == {DATA_WIDTH{1'b0}});
    end
  end

  always @(posedge aclk) begin
    if (f_past_valid) begin
      if (!$past(aresetn)) begin
        assert (!bvalid_q);
        assert (!rvalid_q);
        assert (!aw_held_q);
        assert (!w_held_q);
      end else begin
        if ($past(bvalid_q && !s_axil_bready)) begin
          assert (bvalid_q);
          assert (bresp_q == $past(bresp_q));
        end
        if ($past(rvalid_q && !s_axil_rready)) begin
          assert (rvalid_q);
          assert (rresp_q == $past(rresp_q));
          assert (rdata_q == $past(rdata_q));
        end
        if ($past(do_write)) assert (bvalid_q);
        if ($past(ar_hs)) assert (rvalid_q);
        if (!$past(do_write) && !$past(bvalid_q)) assert (!bvalid_q);
        if (!$past(ar_hs) && !$past(rvalid_q)) assert (!rvalid_q);
      end
    end
  end

  always @(posedge aclk) begin
    if (f_past_valid && aresetn) begin
      cover (bvalid_q && s_axil_bready && (bresp_q == RESP_OKAY));
      cover (rvalid_q && s_axil_rready && (rresp_q == RESP_SLVERR));
    end
  end
`endif

endmodule
=== END FILE ===
