// Self-checking directed testbench for axi4_lite_regs.
// Inputs are driven at the falling edge. Handshakes are sampled 1 time unit
// later, before the rising edge that acts on them.
`define CHECK(cond, msg) begin if (cond) passed = passed + 1; else begin failed = failed + 1; $error msg; end end
`define FAIL(msg) begin failed = failed + 1; $error msg; end

module axi4_lite_regs_tb;

  localparam [1:0] OKAY   = 2'b00;
  localparam [1:0] SLVERR = 2'b10;

  reg         aclk;
  reg         aresetn;
  reg  [3:0]  awaddr;
  reg         awvalid;
  wire        awready;
  reg  [31:0] wdata;
  reg  [3:0]  wstrb;
  reg         wvalid;
  wire        wready;
  wire [1:0]  bresp;
  wire        bvalid;
  reg         bready;
  reg  [3:0]  araddr;
  reg         arvalid;
  wire        arready;
  wire [31:0] rdata;
  wire [1:0]  rresp;
  wire        rvalid;
  reg         rready;

  integer passed;
  integer failed;
  integer rc;
  integer i;
  reg [8*64-1:0] nonce;

  // Reference model of the four registers.
  reg [31:0] m0;
  reg [31:0] m1;
  reg [31:0] m2;
  reg [31:0] m3;

  reg [3:0]  addr_v;
  reg [31:0] data_v;

  // run_txn working state
  reg        t_aw_done;
  reg        t_w_done;
  reg        t_b_done;
  reg        t_ar_done;
  reg        t_r_done;
  reg        t_aw_fire;
  reg        t_w_fire;
  reg        t_ar_fire;
  reg        t_b_fire;
  reg        t_r_fire;
  reg        t_w_complete;
  reg [1:0]  t_exp_bresp;
  reg [1:0]  t_exp_rresp;
  reg [1:0]  t_held_bresp;
  reg [1:0]  t_held_rresp;
  reg [31:0] t_exp_rdata;
  reg [31:0] t_held_rdata;
  integer    t_cyc;
  integer    t_req_w;
  integer    t_req_r;
  integer    t_bv_seen;
  integer    t_rv_seen;

  axi4_lite_regs #(
      .ADDR_WIDTH(4),
      .DATA_WIDTH(32)
  ) dut (
      .aclk          (aclk),
      .aresetn       (aresetn),
      .s_axil_awaddr (awaddr),
      .s_axil_awvalid(awvalid),
      .s_axil_awready(awready),
      .s_axil_wdata  (wdata),
      .s_axil_wstrb  (wstrb),
      .s_axil_wvalid (wvalid),
      .s_axil_wready (wready),
      .s_axil_bresp  (bresp),
      .s_axil_bvalid (bvalid),
      .s_axil_bready (bready),
      .s_axil_araddr (araddr),
      .s_axil_arvalid(arvalid),
      .s_axil_arready(arready),
      .s_axil_rdata  (rdata),
      .s_axil_rresp  (rresp),
      .s_axil_rvalid (rvalid),
      .s_axil_rready (rready)
  );

  initial aclk = 1'b0;
  always #5 aclk = ~aclk;

  // ------------------------------------------------------------------
  // Model helpers
  // ------------------------------------------------------------------
  function mapped_f;
    input [3:0] a;
    begin
      mapped_f = (a[1:0] == 2'b00);
    end
  endfunction

  function [31:0] merge_f;
    input [31:0] o;
    input [31:0] n;
    input [3:0]  s;
    begin
      merge_f = {s[3] ? n[31:24] : o[31:24],
                 s[2] ? n[23:16] : o[23:16],
                 s[1] ? n[15:8]  : o[15:8],
                 s[0] ? n[7:0]   : o[7:0]};
    end
  endfunction

  function [31:0] model_get;
    input [1:0] idx;
    begin
      case (idx)
        2'd0:    model_get = m0;
        2'd1:    model_get = m1;
        2'd2:    model_get = m2;
        default: model_get = m3;
      endcase
    end
  endfunction

  task model_set;
    input [1:0]  idx;
    input [31:0] v;
    begin
      case (idx)
        2'd0:    m0 = v;
        2'd1:    m1 = v;
        2'd2:    m2 = v;
        default: m3 = v;
      endcase
    end
  endtask

  task model_reset;
    begin
      m0 = 32'h0;
      m1 = 32'h0;
      m2 = 32'h0;
      m3 = 32'h0;
    end
  endtask

  // ------------------------------------------------------------------
  // One transaction: an optional write and an optional read, run concurrently.
  // Must be entered just after a falling edge. Returns at a falling edge.
  // ------------------------------------------------------------------
  task run_txn;
    input         do_w;
    input [3:0]   w_addr;
    input [31:0]  w_data;
    input [3:0]   w_strb;
    input integer aw_dly;
    input integer w_dly;
    input integer b_stall;
    input         do_r;
    input [3:0]   r_addr;
    input integer ar_dly;
    input integer r_stall;
    begin
      // Idle at start: after the previous response was taken, every channel is ready again (B2B).
      `CHECK(awready === 1'b1 && wready === 1'b1 && arready === 1'b1, ("start: READY not high when idle (aw=%b w=%b ar=%b)", awready, wready, arready))
      `CHECK(bvalid === 1'b0 && rvalid === 1'b0, ("start: response valid with nothing outstanding (b=%b r=%b)", bvalid, rvalid))

      t_aw_done    = !do_w;
      t_w_done     = !do_w;
      t_b_done     = !do_w;
      t_ar_done    = !do_r;
      t_r_done     = !do_r;
      t_req_w      = -1;
      t_req_r      = -1;
      t_bv_seen    = 0;
      t_rv_seen    = 0;
      t_cyc        = 0;
      t_exp_bresp  = mapped_f(w_addr) ? OKAY : SLVERR;
      t_exp_rresp  = mapped_f(r_addr) ? OKAY : SLVERR;
      t_exp_rdata  = 32'h0;
      t_held_bresp = 2'b00;
      t_held_rresp = 2'b00;
      t_held_rdata = 32'h0;

      awaddr = w_addr;
      wdata  = w_data;
      wstrb  = w_strb;
      araddr = r_addr;

      while (!(t_b_done && t_r_done) && (t_cyc < 64)) begin
        awvalid = !t_aw_done && (t_cyc >= aw_dly);
        wvalid  = !t_w_done && (t_cyc >= w_dly);
        arvalid = !t_ar_done && (t_cyc >= ar_dly);
        bready  = (t_bv_seen >= b_stall);
        rready  = (t_rv_seen >= r_stall);
        #1;

        // ---- B channel ----
        if (t_b_done) begin
          if (bvalid !== 1'b0) `FAIL(("BVALID high with no write outstanding (cycle %0d)", t_cyc))
        end else if (bvalid === 1'b1) begin
          `CHECK(t_aw_done && t_w_done, ("BVALID before both AW and W were accepted (cycle %0d)", t_cyc))
          `CHECK(awready === 1'b0 && wready === 1'b0, ("AWREADY/WREADY high while a write response is pending (cycle %0d)", t_cyc))
          if (t_bv_seen == 0) begin
            `CHECK(t_cyc - t_req_w == 1, ("write latency %0d cycles, expected 1 (spec bound 2)", t_cyc - t_req_w))
            `CHECK(bresp === t_exp_bresp, ("write to 0x%h: BRESP %b, expected %b", w_addr, bresp, t_exp_bresp))
            t_held_bresp = bresp;
          end else begin
            `CHECK(bresp === t_held_bresp, ("BRESP changed while stalled: %b then %b", t_held_bresp, bresp))
          end
        end else if (t_bv_seen != 0) begin
          `FAIL(("BVALID dropped before the response was taken (cycle %0d)", t_cyc))
        end

        // ---- R channel ----
        if (t_r_done) begin
          if (rvalid !== 1'b0) `FAIL(("RVALID high with no read outstanding (cycle %0d)", t_cyc))
        end else if (rvalid === 1'b1) begin
          `CHECK(t_ar_done, ("RVALID before AR was accepted (cycle %0d)", t_cyc))
          `CHECK(arready === 1'b0, ("ARREADY high while read data is pending (cycle %0d)", t_cyc))
          if (t_rv_seen == 0) begin
            `CHECK(t_cyc - t_req_r == 1, ("read latency %0d cycles, expected 1 (spec bound 2)", t_cyc - t_req_r))
            `CHECK(rresp === t_exp_rresp, ("read of 0x%h: RRESP %b, expected %b", r_addr, rresp, t_exp_rresp))
            `CHECK(rdata === t_exp_rdata, ("read of 0x%h: RDATA %h, expected %h", r_addr, rdata, t_exp_rdata))
            t_held_rresp = rresp;
            t_held_rdata = rdata;
          end else begin
            `CHECK(rresp === t_held_rresp && rdata === t_held_rdata, ("R payload changed while stalled: %b/%h then %b/%h", t_held_rresp, t_held_rdata, rresp, rdata))
          end
        end else if (t_rv_seen != 0) begin
          `FAIL(("RVALID dropped before the data was taken (cycle %0d)", t_cyc))
        end

        // ---- What the coming rising edge does ----
        t_aw_fire    = awvalid && (awready === 1'b1);
        t_w_fire     = wvalid && (wready === 1'b1);
        t_ar_fire    = arvalid && (arready === 1'b1);
        t_b_fire     = !t_b_done && (bvalid === 1'b1) && bready;
        t_r_fire     = !t_r_done && (rvalid === 1'b1) && rready;
        t_w_complete = !(t_aw_done && t_w_done) &&
                       (t_aw_done || t_aw_fire) && (t_w_done || t_w_fire);

        // The read samples register state from before this edge's write.
        if (t_ar_fire) begin
          t_req_r     = t_cyc;
          t_exp_rdata = mapped_f(r_addr) ? model_get(r_addr[3:2]) : 32'h0;
        end
        if (t_w_complete) begin
          t_req_w = t_cyc;
          if (mapped_f(w_addr)) begin
            model_set(w_addr[3:2], merge_f(model_get(w_addr[3:2]), w_data, w_strb));
          end
        end
        if (!t_b_done && (bvalid === 1'b1)) t_bv_seen = t_bv_seen + 1;
        if (!t_r_done && (rvalid === 1'b1)) t_rv_seen = t_rv_seen + 1;

        @(negedge aclk);

        if (t_aw_fire) t_aw_done = 1'b1;
        if (t_w_fire)  t_w_done  = 1'b1;
        if (t_ar_fire) t_ar_done = 1'b1;
        if (t_b_fire)  t_b_done  = 1'b1;
        if (t_r_fire)  t_r_done  = 1'b1;
        t_cyc = t_cyc + 1;
      end

      if (!(t_b_done && t_r_done)) `FAIL(("transaction timed out (write %b to 0x%h, read %b of 0x%h)", do_w, w_addr, do_r, r_addr))

      awvalid = 1'b0;
      wvalid  = 1'b0;
      arvalid = 1'b0;
      bready  = 1'b0;
      rready  = 1'b0;
    end
  endtask

  task wr;
    input [3:0]   a;
    input [31:0]  d;
    input [3:0]   s;
    input integer aw_dly;
    input integer w_dly;
    input integer b_stall;
    begin
      run_txn(1'b1, a, d, s, aw_dly, w_dly, b_stall, 1'b0, 4'h0, 0, 0);
    end
  endtask

  task rd;
    input [3:0]   a;
    input integer ar_dly;
    input integer r_stall;
    begin
      run_txn(1'b0, 4'h0, 32'h0, 4'h0, 0, 0, 0, 1'b1, a, ar_dly, r_stall);
    end
  endtask

  task rd_all;
    begin
      rd(4'h0, 0, 0);
      rd(4'h4, 0, 0);
      rd(4'h8, 0, 0);
      rd(4'hC, 0, 0);
    end
  endtask

  // ------------------------------------------------------------------
  // Test sequence
  // ------------------------------------------------------------------
  initial begin
    passed = 0;
    failed = 0;
    nonce  = {8*64{1'b0}};
    rc     = $value$plusargs("nirmaan_nonce=%s", nonce);

    aresetn = 1'b0;
    awaddr  = 4'h0;
    awvalid = 1'b0;
    wdata   = 32'h0;
    wstrb   = 4'h0;
    wvalid  = 1'b0;
    bready  = 1'b0;
    araddr  = 4'h0;
    arvalid = 1'b0;
    rready  = 1'b0;
    model_reset;

    // ---- Reset ----
    repeat (3) @(negedge aclk);
    `CHECK(bvalid === 1'b0 && rvalid === 1'b0, ("BVALID/RVALID not low during reset (b=%b r=%b)", bvalid, rvalid))
    aresetn = 1'b1;

    // Reset values of every register.
    rd_all;

    // ---- Write then read every register, AW and W together ----
    wr(4'h0, 32'h1111_2222, 4'hF, 0, 0, 0);
    wr(4'h4, 32'h3333_4444, 4'hF, 0, 0, 0);
    wr(4'h8, 32'hDEAD_BEEF, 4'hF, 0, 0, 0);
    wr(4'hC, 32'hCAFE_F00D, 4'hF, 0, 0, 0);
    rd_all;

    // ---- AW before W, W before AW, with gaps ----
    wr(4'h4, 32'hA5A5_5A5A, 4'hF, 0, 3, 0);
    rd(4'h4, 0, 0);
    wr(4'h8, 32'h0123_4567, 4'hF, 2, 0, 0);
    rd(4'h8, 0, 0);
    wr(4'h0, 32'h89AB_CDEF, 4'hF, 0, 6, 0);
    wr(4'hC, 32'h7654_3210, 4'hF, 6, 0, 0);
    rd_all;

    // ---- WSTRB partial and empty writes ----
    wr(4'hC, 32'h1122_3344, 4'b0101, 0, 0, 0);
    rd(4'hC, 0, 0);
    wr(4'hC, 32'hFFFF_FFFF, 4'b1000, 0, 0, 0);
    rd(4'hC, 0, 0);
    wr(4'h0, 32'hFFFF_FFFF, 4'b0000, 0, 0, 0);
    rd(4'h0, 0, 0);
    wr(4'h8, 32'hAABB_CCDD, 4'b0110, 3, 0, 2);
    rd(4'h8, 0, 0);
    wr(4'h4, 32'h0000_00EE, 4'b0001, 0, 2, 0);
    rd(4'h4, 0, 0);

    // ---- B and R backpressure ----
    wr(4'h0, 32'h5555_AAAA, 4'hF, 0, 0, 5);
    rd(4'h0, 0, 4);
    wr(4'h4, 32'h1234_5678, 4'hF, 1, 0, 3);
    rd(4'h4, 2, 6);

    // ---- Back-to-back transactions ----
    for (i = 0; i < 4; i = i + 1) begin
      addr_v = {i[1:0], 2'b00};
      data_v = {16'hC0DE, i[7:0], 8'h5A};
      wr(addr_v, data_v, 4'hF, 0, 0, 0);
    end
    for (i = 0; i < 4; i = i + 1) begin
      addr_v = {i[1:0], 2'b00};
      rd(addr_v, 0, 0);
    end

    // ---- SLVERR policy ----
    wr(4'h5, 32'hFFFF_FFFF, 4'hF, 0, 0, 0);
    wr(4'hE, 32'hFFFF_FFFF, 4'hF, 2, 0, 3);
    wr(4'h2, 32'hFFFF_FFFF, 4'h0, 0, 0, 0);
    rd(4'h5, 0, 0);
    rd(4'hE, 0, 2);
    rd(4'h1, 0, 0);
    rd_all;

    // ---- Reads and writes together ----
    run_txn(1'b1, 4'h0, 32'h0F0F_0F0F, 4'hF, 0, 0, 0, 1'b1, 4'hC, 0, 0);
    run_txn(1'b1, 4'h4, 32'hF00D_CAFE, 4'hF, 0, 0, 0, 1'b1, 4'h4, 0, 0);
    rd(4'h4, 0, 0);
    run_txn(1'b1, 4'h8, 32'h2468_ACE0, 4'hF, 1, 2, 4, 1'b1, 4'h8, 0, 3);
    run_txn(1'b1, 4'h6, 32'hBAD0_BAD0, 4'hF, 0, 0, 2, 1'b1, 4'h0, 1, 0);
    run_txn(1'b1, 4'hC, 32'h1357_9BDF, 4'b1100, 0, 3, 1, 1'b1, 4'h9, 0, 2);
    rd_all;

    // ---- Reset during traffic: a half-accepted write is discarded ----
    awaddr  = 4'h4;
    awvalid = 1'b1;
    wvalid  = 1'b0;
    bready  = 1'b0;
    rready  = 1'b0;
    #1;
    `CHECK(awready === 1'b1, ("AWREADY not high before the AW-only handshake"))
    @(negedge aclk);
    awvalid = 1'b0;
    #1;
    `CHECK(awready === 1'b0 && wready === 1'b1, ("AW not held after AW-only handshake (aw=%b w=%b)", awready, wready))
    `CHECK(bvalid === 1'b0, ("BVALID raised before W arrived"))
    aresetn = 1'b0;
    @(negedge aclk);
    @(negedge aclk);
    `CHECK(awready === 1'b1 && wready === 1'b1 && arready === 1'b1, ("READY not high in reset (aw=%b w=%b ar=%b)", awready, wready, arready))
    `CHECK(bvalid === 1'b0 && rvalid === 1'b0, ("BVALID/RVALID not low in reset"))
    aresetn = 1'b1;
    model_reset;
    // A W-first write: if the old AW had survived, this would complete early to REG1.
    wr(4'h8, 32'h7777_8888, 4'hF, 2, 0, 0);
    rd_all;

    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

endmodule
